class CareerPilotApp extends StatelessWidget {
  const CareerPilotApp({super.key});
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false, title: 'CareerPilot AI',
      theme: ThemeData(useMaterial3: true, brightness: Brightness.dark, scaffoldBackgroundColor: const Color(0xFF090D16),
        colorScheme: const ColorScheme.dark(primary: Color(0xFF10B981), secondary: Color(0xFF3B82F6), surface: Color(0xFF111827)),
        appBarTheme: const AppBarTheme(backgroundColor: Color(0xFF090D16), elevation: 0, surfaceTintColor: Colors.transparent),
