}

class Dashboard extends StatefulWidget { const Dashboard({super.key}); @override State<Dashboard> createState() => _DashboardState(); }

class _DashboardState extends State<Dashboard> {
  String filter = 'All'; String searchQuery = ''; int _jobsLimit = 20; int _followupsLimit = 20; bool _showArchived = false;
  String _selectedClientFilter = 'All'; String _activeClientId = 'user'; List<Map<String, dynamic>> _clientsCache = [];
  static const String _hfSpaceUrl = 'https://iharmayau-habeeb-job-bot.hf.space/';
  static const String _ownerId = 'user'; static const String _ownerName = 'Habibu Armayau Isah'; static const String _ownerSkill = 'Flutter + AI'; static const String _ownerType = 'freelancer';
  static const List<String> _recruiterWords = ['recruitment','recruiting','recruiter','staffing','headhunter','executive search','talent agency','talent acquisition','placement agency','job agency','employment agency','job board','recruitment agency','recruitment firm','workforce','manpower'];
  bool _isRecruiterName(String c) { final x=c.toLowerCase(); return _recruiterWords.any((w)=>x.contains(w)); }
  String _normalizeSkill(String r){ final s=r.trim(); if(s.isEmpty) return 'FLUTTER'; return s.toUpperCase(); }
  String _skillDisplay(String r){ final s=r.trim(); if(s.isEmpty) return 'Flutter'; if(s.toUpperCase()=='FLUTTER') return 'Flutter'; if(s.toUpperCase()=='BACKEND') return 'Backend'; if(s.toUpperCase()=='AI'||s.toUpperCase()=='LLM') return 'AI'; if(s.toUpperCase()=='FULLSTACK') return 'Full-Stack'; return s.toLowerCase().split(' ').map((w)=>w.isEmpty?w:w[0].toUpperCase()+w.substring(1)).join(' '); }
  String _roleLineForSkill(String r){ final s=r.trim().toUpperCase(); if(s=='FLUTTER') return 'Flutter + AI mobile apps'; if(s=='BACKEND') return 'backend systems and APIs'; if(s=='AI'||s=='LLM') return 'AI features, LLM apps and automation'; if(s=='FULLSTACK') return 'full-stack web and mobile apps'; if(s.isEmpty) return 'Flutter + AI mobile apps'; return _skillDisplay(r); }
  String _displayNameForClient(Map<String,dynamic> c){ final id=(c['id']??'').toString(); final raw=(c['name']??'').toString().trim(); if(raw.isNotEmpty) return raw; if(id==_ownerId) return _ownerName; return 'Unnamed Client'; }
  String _displaySkillForClient(Map<String,dynamic> c){ final id=(c['id']??'').toString(); final raw=(c['job_wanted']??c['job']??c['skill']??'').toString().trim(); if(raw.isNotEmpty) return raw; if(id==_ownerId) return _ownerSkill; return ''; }
  String _displayTypeForClient(Map<String,dynamic> c){ final raw=(c['client_type']??'').toString().trim(); if(raw.isNotEmpty) return raw; if((c['id']??'').toString()==_ownerId) return _ownerType; return 'freelancer'; }
  String _activeClientDisplayName(){ if(_activeClientId==_ownerId) return _ownerName; final m=_clientsCache.where((c)=>(c['id']??'').toString()==_activeClientId).toList(); if(m.isNotEmpty) return _displayNameForClient(m.first); return _activeClientId; }
  @override void initState(){ super.initState(); _loadActiveClient(); _ensureDefaultUserProfile(); }
  Future<void> _loadActiveClient() async { try{ final doc=await FirebaseFirestore.instance.collection('bot_config').doc('active').get(); if(doc.exists){ final d=doc.data()??{}; if(mounted) setState(()=>_activeClientId=(d['active_client_id']??d['client_id']??'user').toString()); } }catch(_){} }
  Future<void> _ensureDefaultUserProfile() async { try{ final ref=FirebaseFirestore.instance.collection('clients').doc(_ownerId); final doc=await ref.get(); if(!doc.exists){ await ref.set({'name':_ownerName,'client_type':_ownerType,'skill':_ownerSkill,'job_wanted':'','job':'','location':'Lagos, Nigeria','place':'Lagos, Nigeria / Global','email':'','phone':'','cv_url':'','cvUrl':'','cvLink':'','gmail_connected':false,'is_paused':false,'status':'active','max_per_day':20,'is_owner':true,'created_at':DateTime.now().toIso8601String()}); } }catch(_){} }

  // ===== V81 EXPORT =====
  Future<List<Map<String,dynamic>>> _fetchClientFullJobs(Map<String,dynamic> client) async {
    final clientId=(client['id']??'').toString(); final clientName=_displayNameForClient(client); final db=FirebaseFirestore.instance; List<Map<String,dynamic>> all=[];
    try{ final q1=await db.collection('jobs_sent').where('client_id',isEqualTo:clientId).get(); for(final d in q1.docs){ final m=d.data(); if((m['archived']??false)==true) continue; m['doc_id']=d.id; all.add(m);} }catch(_){}
    try{ final q2=await db.collection('jobs_sent').where('client_name',isEqualTo:clientName).get(); for(final d in q2.docs){ final m=d.data(); if((m['archived']??false)==true) continue; final ex=all.any((e)=>(e['company']??'')==(m['company']??'')&&(e['email']??'')==(m['email']??'')); if(!ex){ m['doc_id']=d.id; all.add(m);} } }catch(_){}
    for(int i=0;i<all.length;i++){ final comp=(all[i]['company']??'').toString(); final em=(all[i]['email']??'').toString(); if(comp.isEmpty) continue; try{ QuerySnapshot q; if(em.isNotEmpty){ q=await db.collection('jobs_sent_details').where('company',isEqualTo:comp).where('email',isEqualTo:em).limit(1).get(); } else { q=await db.collection('jobs_sent_details').where('company',isEqualTo:comp).limit(1).get(); } if(q.docs.isNotEmpty){ final d=q.docs.first.data() as Map<String,dynamic>; if((all[i]['phone']??'').toString().isEmpty&&(d['phone']??'').toString().isNotEmpty) all[i]['phone']=d['phone']; if((all[i]['website']??'').toString().isEmpty&&(d['website']??d['url']??'').toString().isNotEmpty) all[i]['website']=d['website']??d['url']; if((all[i]['subject']??'').toString().isEmpty&&(d['subject']??d['email_subject']??'').toString().isNotEmpty) all[i]['subject']=d['subject']??d['email_subject']; if((all[i]['email_body']??'').toString().isEmpty&&(d['email_body']??d['body']??'').toString().isNotEmpty) all[i]['email_body']=d['email_body']??d['body']; } }catch(_){} }
    try{ final rq=await db.collection('jobs_replies').get(); final replies=rq.docs.map((d)=>d.data() as Map<String,dynamic>).toList(); for(int i=0;i<all.length;i++){ final comp=(all[i]['company']??'').toString().toLowerCase().trim(); final em=(all[i]['email']??'').toString().toLowerCase().trim(); final found=replies.where((r){ final rc=(r['company']??'').toString().toLowerCase().trim(); final re=(r['email']??'').toString().toLowerCase().trim(); return (comp.isNotEmpty&&rc==comp)||(em.isNotEmpty&&re==em); }).toList(); all[i]['reply_status']=found.isNotEmpty?'Replied':'No reply yet'; if(found.isNotEmpty) all[i]['reply_subject']=found.first['subject']??''; } }catch(_){ for(var j in all){ j['reply_status']='No reply yet'; } }
    all.sort((a,b){ final da=_parseDate(a['timestamp']??a['date']); final db2=_parseDate(b['timestamp']??b['date']); if(da==null&&db2==null) return 0; if(da==null) return 1; if(db2==null) return -1; return db2.compareTo(da); });
    return all;
  }
  Future<List<Map<String,dynamic>>> _fetchClientSentJobs(Map<String,dynamic> c) async => _fetchClientFullJobs(c);
  int _packageTarget(Map<String,dynamic> c){ final v=c['package_total']; if(v is int&&v>0) return v; if(v is String){ final p=int.tryParse(v); if(p!=null&&p>0) return p; } return 50; }
  String _buildWhatsAppReport(Map<String,dynamic> client, List<Map<String,dynamic>> jobs){
    final name=_displayNameForClient(client); final skill=_displaySkillForClient(client); final target=_packageTarget(client); final sent=jobs.length; final rem=target-sent<0?0:target-sent; final buf=StringBuffer();
    buf.writeln('CareerPilot AI - Weekly Report'); buf.writeln('Client: $name'); if(skill.isNotEmpty) buf.writeln('Job / Skill: $skill'); buf.writeln('Package: $target companies'); buf.writeln('Sent: $sent / $target - Remaining: $rem'); buf.writeln('--------------------------------');
    if(jobs.isEmpty){ buf.writeln('No emails sent yet. We will start sending today.'); } else { for(int i=0;i<jobs.length;i++){ final j=jobs[i]; final comp=(j['company']??'Unknown').toString(); final em=(j['email']??'').toString(); final date=_formatDate(j['timestamp']); final sd=date.isNotEmpty?date.split(' ').first:''; buf.writeln('${i+1}. $comp - $em - $sd'); } }
    buf.writeln('--------------------------------'); buf.writeln('Thank you for using CareerPilot AI.'); return buf.toString();
  }
  Future<void> _shareWhatsAppReport(Map<String,dynamic> client) async {
    try{ if(mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Generating WhatsApp report...'), backgroundColor: Color(0xFF10B981), duration: Duration(seconds: 1))); final jobs=await _fetchClientFullJobs(client); final text=_buildWhatsAppReport(client,jobs); final name=_displayNameForClient(client); await Clipboard.setData(ClipboardData(text:text)); final phone=_cleanPhone(client['phone']); if(phone.isNotEmpty){ final digits=_phoneDigits(phone); if(digits.isNotEmpty){ final uri=Uri.parse('https://wa.me/$digits?text=${Uri.encodeComponent(text)}'); if(await launchUrl(uri,mode: LaunchMode.externalApplication)) return; } } await Share.share(text,subject:'CareerPilot Report - $name'); }catch(e){ if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Export failed: $e'),backgroundColor:Colors.red)); }
  }
