  // V81 EXPORT ALL CLIENTS - One PDF for your own record
  Future<void> _exportAllClientsPdf() async {
    try{
      if(mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Generating All Clients PDF...'),backgroundColor:Color(0xFF10B981),duration:Duration(seconds:1)));
      // Use cache, fallback to Firestore if empty
      List<Map<String,dynamic>> clients=_clientsCache;
      if(clients.isEmpty){ final s=await FirebaseFirestore.instance.collection('clients').get(); clients=s.docs.map((d){ final m=d.data(); m['id']=d.id; return m; }).toList(); }
      final pdf=pw.Document(); final nowStr=_formatDate(DateTime.now().toIso8601String());
      // Fetch all clients data first
      List<Map<String,dynamic>> allData=[];
      int grandSent=0; int grandReplied=0;
      for(final c in clients){ final jobs=await _fetchClientFullJobs(c); final sent=jobs.length; final replied=jobs.where((j)=>(j['reply_status']??'')=='Replied').length; grandSent+=sent; grandReplied+=replied; allData.add({'client':c,'jobs':jobs,'sent':sent,'replied':replied,'target':_packageTarget(c)}); }
      pdf.addPage(pw.MultiPage(pageFormat: PdfPageFormat.a4, margin: const pw.EdgeInsets.all(24), build:(ctx)=>[
        pw.Row(mainAxisAlignment:pw.MainAxisAlignment.spaceBetween,children:[ pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[ pw.Text('CareerPilot AI',style:pw.TextStyle(fontSize:22,fontWeight:pw.FontWeight.bold,color:PdfColors.green900)), pw.Text('All Clients - Master Report',style:const pw.TextStyle(fontSize:12,color:PdfColors.grey700)) ]), pw.Container(padding:const pw.EdgeInsets.symmetric(horizontal:10,vertical:6),decoration:pw.BoxDecoration(color:PdfColors.green50,borderRadius:pw.BorderRadius.circular(8)),child:pw.Text('MASTER REPORT',style:pw.TextStyle(fontSize:9,fontWeight:pw.FontWeight.bold,color:PdfColors.green900))) ]),
        pw.SizedBox(height:16), pw.Divider(), pw.SizedBox(height:12), pw.Text('Generated: $nowStr',style:const pw.TextStyle(fontSize:11,color:PdfColors.grey600)), pw.SizedBox(height:4), pw.Text('Total Clients: ${clients.length} - Total Sent: $grandSent - Total Replied: $grandReplied',style:pw.TextStyle(fontSize:13,fontWeight:pw.FontWeight.bold)), pw.SizedBox(height:20),
        ...allData.map((entry){
          final c=entry['client'] as Map<String,dynamic>; final jobs=entry['jobs'] as List<Map<String,dynamic>>; final sent=entry['sent'] as int; final target=entry['target'] as int; final replied=entry['replied'] as int; final rem=target-sent<0?0:target-sent; final name=_displayNameForClient(c); final skill=_displaySkillForClient(c); final type=_displayTypeForClient(c);
          return pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[
            pw.Container(width:double.infinity,padding:const pw.EdgeInsets.all(12),decoration:pw.BoxDecoration(color:PdfColors.green900,borderRadius:pw.BorderRadius.circular(8)),child:pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[ pw.Text(name,style:pw.TextStyle(fontSize:15,fontWeight:pw.FontWeight.bold,color:PdfColors.white)), pw.SizedBox(height:2), pw.Text('${type=='job_seeker'?'Job Seeker':'Freelancer'} - $skill - Sent: $sent / $target - Remaining: $rem - Replied: $replied',style:const pw.TextStyle(fontSize:11,color:PdfColors.white)) ])),
            pw.SizedBox(height:10),
            if(jobs.isEmpty) pw.Text('No emails sent yet for this client.',style:const pw.TextStyle(fontSize:11,color:PdfColors.grey600)) else ...jobs.asMap().entries.map((e){ final idx=e.key+1; final j=e.value; final comp=(j['company']??'Unknown').toString(); final em=(j['email']??'').toString(); final phone=_cleanPhone(j['phone']).isNotEmpty?_cleanPhone(j['phone']):'Not available'; final web=(j['website']??'').toString().isNotEmpty?(j['website']??'').toString():'Not available'; final date=_formatDate(j['timestamp']); final sd=date.isNotEmpty?date.split(' ').first:'Unknown'; final rs=(j['reply_status']??'No reply yet').toString(); return pw.Container(margin:const pw.EdgeInsets.only(bottom:6),padding:const pw.EdgeInsets.all(10),decoration:pw.BoxDecoration(border:pw.Border.all(color:PdfColors.grey300),borderRadius:pw.BorderRadius.circular(6)),child:pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[ pw.Text('$idx. $comp - $rs',style:pw.TextStyle(fontSize:12,fontWeight:pw.FontWeight.bold)), pw.Text('Email: $em | Phone: $phone',style:const pw.TextStyle(fontSize:10)), pw.Text('Website: $web | Date: $sd',style:const pw.TextStyle(fontSize:10)) ])); }),
            pw.SizedBox(height:20),
          ]);
        }),
        pw.Text('CareerPilot AI - Habeeb Armayau Isah',style:const pw.TextStyle(fontSize:11,color:PdfColors.grey600)),
      ]));
      await Printing.sharePdf(bytes:await pdf.save(),filename:'CareerPilot_All_Clients_Report.pdf');
      if(mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('All Clients PDF ready - Save to Files to download.'),backgroundColor:Color(0xFF10B981)));
    }catch(e){ if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('All Clients PDF failed: $e'),backgroundColor:Colors.red)); }
  }

  // ===== Helpers =====
  Future<Map<String,int>> _fetchDashboardCounts() async { final db=FirebaseFirestore.instance; int totalAll=0,arch=0,today=0; try{ final a=await db.collection('jobs_sent').count().get(); totalAll=a.count??0; }catch(_){ try{ final s=await db.collection('jobs_sent').get(); totalAll=s.docs.length; }catch(_){} } try{ final a=await db.collection('jobs_sent').where('archived',isEqualTo:true).count().get(); arch=a.count??0; }catch(_){} int total=totalAll-arch; if(total<0) total=0; try{ final now=DateTime.now(); final dk=_dayKey(now); final a=await db.collection('jobs_sent').where('date',isEqualTo:dk).count().get(); today=a.count??0; }catch(_){} return {'total':total,'today':today,'archived':arch}; }
  Future<int> _fetchFilteredTotal() async { if(_selectedClientFilter=='All'){ final m=await _fetchDashboardCounts(); return m['total']??0; } try{ final db=FirebaseFirestore.instance; final f=_selectedClientFilter.toLowerCase(); final match=_clientsCache.where((c)=>(c['id']??'').toString().toLowerCase()==f).toList(); final name=match.isNotEmpty?(match.first['name']??'').toString():f; int c1=0,c2=0; try{ final a=await db.collection('jobs_sent').where('client_name',isEqualTo:name).count().get(); c1=a.count??0; }catch(_){} try{ final a=await db.collection('jobs_sent').where('client_id',isEqualTo:f).count().get(); c2=a.count??0; }catch(_){} return c1>c2?c1:c2; }catch(_){ return 0; } }
