  String _formatDate(dynamic ts){ if(ts==null) return ''; if(ts is Timestamp){ final d=ts.toDate(); return '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')} ${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}'; } final s=ts.toString(); if(s.length>16) return s.substring(0,16).replaceAll('T',' '); return s; }
  DateTime? _parseDate(dynamic ts){ if(ts==null) return null; try{ if(ts is Timestamp) return ts.toDate(); final s=ts.toString(); if(s.isEmpty) return null; return DateTime.tryParse(s); }catch(_){ return null; } }
  String _dayKey(DateTime d)=> '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
  String _dayLabel(DateTime d){ const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun']; return days[d.weekday-1]; }
