  String _buildEmailBody(Map<String,dynamic> j){ final saved=(j['email_body']??j['message']??j['body']??j['email_text']??'').toString().trim(); if(saved.isNotEmpty) return saved; final comp=(j['company']??'your team').toString(); final jt=(j['job_type']??j['skill']??'FLUTTER').toString(); final why=(j['why']??j['reason']??'').toString().trim(); final ct=(j['client_type']??'').toString(); final cn=(j['client_name']??'Habeeb').toString(); if(ct=='job_seeker'){ final job=(j['job_wanted']??j['job']??jt).toString(); return "Dear Hiring Manager at $comp,\n\nMy name is $cn. I am applying for the $job position at $comp.\n\n${why.isNotEmpty?why:'I saw $comp is hiring and I am interested in the $job role.'}\n\nI have attached my CV. Thank you.\n\nKind regards,\n$cn"; } final sd=_skillDisplay(jt); final rl=_roleLineForSkill(jt); final wl=why.isNotEmpty?why:"I came across $comp and liked what you're building - I help teams with $sd."; return "Hi $comp Team,\n\n$wl\n\nI'm Habeeb Armaya'u, a Software Engineer. I help teams with $rl.\n\nWould you be open to a quick 10-minute call?\n\nBest regards,\nHabeeb Armaya'u\n$sd Developer"; }
  String _buildSubject(Map<String,dynamic> j){ final saved=(j['subject']??j['email_subject']??'').toString().trim(); if(saved.isNotEmpty) return saved; final comp=(j['company']??'').toString(); final jt=(j['job_type']??j['skill']??'FLUTTER').toString(); if((j['client_type']??'').toString()=='job_seeker'){ return "Application for $jt at $comp - ${(j['client_name']??'Applicant')}"; } return "${_skillDisplay(jt)} Developer for $comp - Can I help your team ship faster? ($jt)"; }
